good_example:
def importar_imagen(url):
    host = obtener_host(url)
    if not es_dominio_permitido(host) or es_ip_privada(resolver(host)):
        raise ValueError("destino no permitido")
    respuesta = requests.get(url, allow_redirects=False)
    return respuesta.content

