good_example:
def descargar(nombre_archivo):
    base = Path("/var/app/descargas").resolve()
    ruta = (base / nombre_archivo).resolve()
    if base not in ruta.parents and ruta != base:
        raise ValueError("ruta no permitida")
    return open(ruta, "rb").read()
